def generar_etiquetas_pdf(lista_prendas, tasa_cambio):
    """Genera un PDF con etiquetas listas para imprimir (3 columnas x 8 filas por página A4)."""
    if not PDF_DISPONIBLE:
        return None
    try:
        pdf = FPDF(orientation="P", unit="mm", format="A4")
        pdf.set_auto_page_break(auto=False)
        pdf.add_page()

        ancho_etiqueta = 62
        alto_etiqueta = 32
        margen_x = 10
        margen_y = 10
        espacio_x = 2
        espacio_y = 2
        cols = 3
        filas_por_pagina = 8

        for idx, prenda in enumerate(lista_prendas):
            pos = idx % (cols * filas_por_pagina)
            if pos == 0 and idx > 0:
                pdf.add_page()

            col = pos % cols
            fila = pos // cols

            x = margen_x + col * (ancho_etiqueta + espacio_x)
            y = margen_y + fila * (alto_etiqueta + espacio_y)

            try:
                pdf.set_dash_pattern(dash=0.8, gap=0.8)
            except Exception:
                pass
            pdf.set_draw_color(74, 111, 165)
            pdf.set_line_width(0.3)
            pdf.rect(x, y, ancho_etiqueta, alto_etiqueta)
            try:
                pdf.set_dash_pattern()
            except Exception:
                pass

            pdf.set_xy(x, y + 1.5)
            pdf.set_font("Helvetica", "B", 8)
            pdf.set_text_color(74, 111, 165)
            pdf.cell(ancho_etiqueta, 4, "LEWIN BOUTIQUE", align="C")

            pdf.set_xy(x, y + 6)
            pdf.set_font("Helvetica", "B", 9)
            pdf.set_text_color(30, 30, 30)
            nombre = str(prenda["Producto"])[:30]
            pdf.cell(ancho_etiqueta, 4, nombre, align="C")

            pdf.set_font("Helvetica", "", 7)
            pdf.set_text_color(80, 80, 80)
            pdf.set_xy(x + 3, y + 12)
            pdf.cell(20, 3.5, f"ID: {prenda['ID']}")
            pdf.set_xy(x + 3, y + 15)
            pdf.cell(20, 3.5, f"Talla: {prenda['talla']}")
            pdf.set_xy(x + 3, y + 18)
            pdf.cell(30, 3.5, f"Color: {prenda['color']}")

            precio_usd = float(prenda.get("precio_venta", 0) or 0)
            pdf.set_xy(x, y + 22)
            pdf.set_font("Helvetica", "B", 14)
            pdf.set_text_color(74, 111, 165)
            pdf.cell(ancho_etiqueta, 6, f"${precio_usd:,.2f}", align="C")

            if tasa_cambio > 0:
                precio_bs = precio_usd * tasa_cambio
                pdf.set_xy(x, y + 27.5)
                pdf.set_font("Helvetica", "", 7)
                pdf.set_text_color(120, 120, 120)
                pdf.cell(ancho_etiqueta, 3, f"{precio_bs:,.2f} Bs", align="C")

        return bytes(pdf.output())
    except Exception as e:
        st.warning(f"No se pudo generar el PDF de etiquetas: {e}")
        return None


@st.cache_data(ttl=3600, show_spinner=False)
def descargar_imagen_bytes(url):
    """Descarga una imagen por URL y la guarda en caché 1 hora (evita repetir la petición en cada clic)."""
    try:
        resp = requests.get(url, timeout=8)
        if resp.status_code == 200:
            return resp.content
    except Exception:
        pass
    return None


def generar_ficha_como_imagen(prenda, tasa_cambio):
    """Genera la ficha del producto como imagen PNG (diseño centrado y compacto, renderizado a 2x para nitidez)."""
    try:
        ESCALA = 2
        ancho_final, alto_final = 540, 640

        ancho = 540 * ESCALA
        alto_foto = 400 * ESCALA
        alto_info = 140 * ESCALA
        alto_bottom = 100 * ESCALA
        alto = alto_foto + alto_info + alto_bottom  # 1280 (a 2x)
        img = Image.new("RGB", (ancho, alto), (255, 255, 255))
        draw = ImageDraw.Draw(img)

        # Fuentes (tamaños x ESCALA para que el downscale final salga nítido)
        try:
            font_nombre = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 22 * ESCALA)
            font_info = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 14 * ESCALA)
            font_precio = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 28 * ESCALA)
            font_precio_bs = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 14 * ESCALA)
            font_escanea = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 16 * ESCALA)
            font_subtexto = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 12 * ESCALA)
            font_contacto = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 11 * ESCALA)
        except Exception:
            font_nombre = ImageFont.load_default()
            font_info = ImageFont.load_default()
            font_precio = ImageFont.load_default()
            font_precio_bs = ImageFont.load_default()
            font_escanea = ImageFont.load_default()
            font_subtexto = ImageFont.load_default()
            font_contacto = ImageFont.load_default()

        def centrar_x(texto, font):
            bbox = draw.textbbox((0, 0), texto, font=font)
            return (ancho - (bbox[2] - bbox[0])) // 2

        # ===== 1) FOTO (400px de alto, full width, sin márgenes) =====
        draw.rectangle([(0, 0), (ancho, alto_foto)], fill=(245, 243, 255))

        if prenda.get("foto_url"):
            try:
                foto_bytes = descargar_imagen_bytes(prenda["foto_url"])
                if foto_bytes:
                    foto = Image.open(BytesIO(foto_bytes)).convert("RGB")
                    # Crop to cover (llenar el espacio sin deformar)
                    ratio_dest = ancho / alto_foto
                    ratio_foto = foto.width / foto.height
                    if ratio_foto > ratio_dest:
                        nuevo_alto = alto_foto
                        nuevo_ancho = int(alto_foto * ratio_foto)
                        foto = foto.resize((nuevo_ancho, nuevo_alto))
                        offset_x = (nuevo_ancho - ancho) // 2
                        foto = foto.crop((offset_x, 0, offset_x + ancho, alto_foto))
                    else:
                        nuevo_ancho = ancho
                        nuevo_alto = int(ancho / ratio_foto)
                        foto = foto.resize((nuevo_ancho, nuevo_alto))
                        offset_y = (nuevo_alto - alto_foto) // 2
                        foto = foto.crop((0, offset_y, ancho, offset_y + alto_foto))
                    img.paste(foto, (0, 0))
            except Exception:
                pass

        # ===== LOGO OVERLAY (centrado, mitad en la foto y mitad en el bloque info) =====
        try:
            logo_bytes_dl = descargar_imagen_bytes(LOGO_URL)
            if logo_bytes_dl:
                logo_img = Image.open(BytesIO(logo_bytes_dl)).convert("RGBA")
                logo_img.thumbnail((60 * ESCALA, 40 * ESCALA))
                w_fondo, h_fondo = 80 * ESCALA, 60 * ESCALA
                fondo_logo = Image.new("RGBA", (w_fondo, h_fondo), (0, 0, 0, 0))
                draw_fondo = ImageDraw.Draw(fondo_logo)
                draw_fondo.rounded_rectangle([(0, 0), (w_fondo - 1, h_fondo - 1)], radius=12 * ESCALA, fill=(255, 255, 255, 255))
                offset_logo_x = (w_fondo - logo_img.width) // 2
                offset_logo_y = (h_fondo - logo_img.height) // 2
                fondo_logo.paste(logo_img, (offset_logo_x, offset_logo_y), logo_img)
                x_logo = (ancho - w_fondo) // 2
                y_logo = alto_foto - h_fondo // 2  # mitad dentro de la foto, mitad fuera
                img.paste(fondo_logo, (x_logo, y_logo), fondo_logo)
        except Exception:
            pass

        # ===== 2) BLOQUE BLANCO DE INFO (140px de alto, todo centrado) =====
        y_info = alto_foto

        # a) Nombre del producto: "ID — Nombre", centrado, 15px desde el inicio del bloque
        id_prenda = str(prenda.get("ID", "")).strip()
        nombre_prenda = str(prenda.get("Producto", "")).strip()
        nombre = f"{id_prenda} — {nombre_prenda}" if id_prenda else nombre_prenda
        y_nombre = y_info + 15 * ESCALA
        draw.text((centrar_x(nombre, font_nombre), y_nombre), nombre, fill=(30, 41, 59), font=font_nombre)
        bbox_nombre = draw.textbbox((0, y_nombre), nombre, font=font_nombre)
        y_tras_nombre = bbox_nombre[3]

        # b) Línea "Talla: X · Color: X", centrada, 8px debajo del nombre
        talla_color_txt = f"Talla: {prenda.get('talla', '-')} · Color: {prenda.get('color', '-')}"
        y_talla_color = y_tras_nombre + 8 * ESCALA
        draw.text((centrar_x(talla_color_txt, font_info), y_talla_color), talla_color_txt, fill=(100, 116, 139), font=font_info)
        bbox_talla_color = draw.textbbox((0, y_talla_color), talla_color_txt, font=font_info)
        y_tras_talla_color = bbox_talla_color[3]

        # c) Precio USD, centrado, 12px debajo de la línea info
        precio_usd = float(prenda.get("precio_venta", 0) or 0)
        precio_txt = f"${precio_usd:,.2f}"
        y_precio = y_tras_talla_color + 12 * ESCALA
        draw.text((centrar_x(precio_txt, font_precio), y_precio), precio_txt, fill=(74, 111, 165), font=font_precio)
        bbox_precio = draw.textbbox((0, y_precio), precio_txt, font=font_precio)
        y_tras_precio = bbox_precio[3]

        # d) Precio Bs, centrado, 4px debajo del precio USD
        if tasa_cambio > 0 and precio_usd > 0:
            bs_txt = f"{precio_usd * tasa_cambio:,.2f} Bs"
            y_bs = y_tras_precio + 4 * ESCALA
            draw.text((centrar_x(bs_txt, font_precio_bs), y_bs), bs_txt, fill=(148, 163, 184), font=font_precio_bs)

        # ===== 3) BLOQUE AZUL INFERIOR (100px de alto, padding 15px) =====
        y_bottom = y_info + alto_info
        draw.rectangle([(0, y_bottom), (ancho, alto)], fill=(74, 111, 165))

        pad_bottom = 15 * ESCALA
        qr_size_total = 80 * ESCALA

        # a) QR a la izquierda (fondo blanco 80x80, padding 8px, radius 6px)
        x_qr = pad_bottom
        y_qr = y_bottom + (alto_bottom - qr_size_total) // 2
        draw.rounded_rectangle(
            [(x_qr, y_qr), (x_qr + qr_size_total, y_qr + qr_size_total)],
            radius=6 * ESCALA, fill=(255, 255, 255),
        )
        if QR_DISPONIBLE:
            qr_bytes_data = generar_qr_bytes(URL_CATALOGO_WEB)
            if qr_bytes_data:
                pad_qr = 8 * ESCALA
                qr_interior = qr_size_total - pad_qr * 2
                qr_img = Image.open(BytesIO(qr_bytes_data)).convert("RGB")
                qr_img = qr_img.resize((qr_interior, qr_interior))
                img.paste(qr_img, (x_qr + pad_qr, y_qr + pad_qr))

        # b) Textos a la derecha del QR, centrados verticalmente con el QR
        x_texto = x_qr + qr_size_total + 20 * ESCALA
        centro_y = y_bottom + alto_bottom // 2
        draw.text((x_texto, centro_y - 28 * ESCALA), "Escanea el QR", fill=(255, 255, 255), font=font_escanea)
        draw.text((x_texto, centro_y - 6 * ESCALA), "para ver más productos", fill=(255, 255, 255), font=font_subtexto)

        pie_textos = []
        if WHATSAPP_BOUTIQUE:
            num = WHATSAPP_BOUTIQUE
            if len(num) == 12:
                num_formateado = f"+{num[:2]} {num[2:5]} {num[5:8]} {num[8:]}"
            else:
                num_formateado = f"+{num}"
            pie_textos.append(f"WA: {num_formateado}")
        if INSTAGRAM_BOUTIQUE:
            pie_textos.append(INSTAGRAM_BOUTIQUE)
        if pie_textos:
            texto_pie = " · ".join(pie_textos)
            draw.text((x_texto, centro_y + 14 * ESCALA), texto_pie, fill=(255, 255, 255), font=font_contacto)

        # Downscale final a la nitidez pedida (2x -> tamaño real, filtro BICUBIC)
        img_final = img.resize((ancho_final, alto_final), Image.BICUBIC)

        # Guardar
        buf = BytesIO()
        img_final.save(buf, format="PNG")
        return buf.getvalue()
    except Exception as e:
        st.warning(f"No se pudo generar la ficha como imagen: {e}")
        return None


def generar_ficha_digital_pdf(prenda, tasa_cambio):
    """Genera un PDF con formato de ficha digital para compartir por WhatsApp."""
    if not PDF_DISPONIBLE:
        return None
    try:
        ancho_mm = 90
        alto_mm = 150
        pdf = FPDF(orientation="P", unit="mm", format=(ancho_mm, alto_mm))
        pdf.add_page()
        pdf.set_auto_page_break(auto=False)

        # ===== BANDA SUPERIOR CON LOGO =====
        pdf.set_fill_color(74, 111, 165)
        pdf.rect(0, 0, ancho_mm, 20, style="F")
        try:
            logo_bytes = base64.b64decode(LOGO_LEWIN_BASE64)
            pdf.image(BytesIO(logo_bytes), x=5, y=3, w=12, type="PNG")
        except Exception:
            pass
        pdf.set_xy(20, 5)
        pdf.set_font("Helvetica", "B", 13)
        pdf.set_text_color(255, 255, 255)
        pdf.cell(0, 5, "LEWIN BOUTIQUE", ln=True)
        pdf.set_xy(20, 11)
        pdf.set_font("Helvetica", "", 8)
        pdf.set_text_color(235, 230, 255)
        pdf.cell(0, 4, "Boutique", ln=True)

        # ===== FOTO DEL PRODUCTO =====
        y_foto = 24
        ancho_foto = ancho_mm - 10
        alto_foto = 55
        pdf.set_fill_color(245, 243, 255)
        pdf.rect(5, y_foto, ancho_foto, alto_foto, style="F")
        if prenda.get("foto_url"):
            try:
                foto_bytes_pdf = descargar_imagen_bytes(prenda["foto_url"])
                if foto_bytes_pdf:
                    img_buf = BytesIO(foto_bytes_pdf)
                    pdf.image(img_buf, x=5, y=y_foto, w=ancho_foto, h=alto_foto)
            except Exception:
                pass
        pdf.set_draw_color(74, 111, 165)
        pdf.set_line_width(0.3)
        pdf.rect(5, y_foto, ancho_foto, alto_foto)

        # ===== NOMBRE DEL PRODUCTO =====
        pdf.set_xy(5, 82)
        pdf.set_font("Helvetica", "B", 12)
        pdf.set_text_color(30, 30, 30)
        pdf.cell(ancho_foto, 6, str(prenda.get("Producto", ""))[:35], align="C")

        # ===== TALLA Y COLOR =====
        pdf.set_xy(5, 89)
        pdf.set_font("Helvetica", "", 9)
        pdf.set_text_color(90, 80, 130)
        pdf.cell(ancho_foto, 4, f"Talla: {prenda.get('talla', '-')}   |   Color: {prenda.get('color', '-')}", align="C")

        # ===== PRECIO EN DOLARES =====
        precio_usd = float(prenda.get("precio_venta", 0) or 0)
        pdf.set_xy(5, 95)
        pdf.set_font("Helvetica", "B", 22)
        pdf.set_text_color(74, 111, 165)
        pdf.cell(ancho_foto, 12, f"${precio_usd:,.2f}", align="C")

        # ===== PRECIO EN BOLIVARES (opcional) =====
        if tasa_cambio > 0 and precio_usd > 0:
            pdf.set_xy(5, 108)
            pdf.set_font("Helvetica", "", 9)
            pdf.set_text_color(140, 140, 140)
            pdf.cell(ancho_foto, 4, f"{precio_usd * tasa_cambio:,.2f} Bs", align="C")

        # ===== QR AL CATALOGO =====
        if QR_DISPONIBLE:
            qr_bytes = generar_qr_bytes(URL_CATALOGO_WEB)
            if qr_bytes:
                qr_buf = BytesIO(qr_bytes)
                pdf.image(qr_buf, x=(ancho_mm - 26) / 2, y=116, w=26, h=26)
                pdf.set_xy(5, 143)
                pdf.set_font("Helvetica", "", 7)
                pdf.set_text_color(120, 120, 120)
                pdf.cell(ancho_foto, 4, "Escanea para ver mas productos", align="C")

        # ===== PIE DE CONTACTO =====
        pie_textos = []
        if WHATSAPP_BOUTIQUE:
            pie_textos.append(f"WA: {WHATSAPP_BOUTIQUE}")
        if INSTAGRAM_BOUTIQUE:
            pie_textos.append(INSTAGRAM_BOUTIQUE)
        if pie_textos:
            pdf.set_xy(5, 145)
            pdf.set_font("Helvetica", "", 7)
            pdf.set_text_color(140, 140, 140)
            pdf.cell(ancho_foto, 4, " | ".join(pie_textos), align="C")

        return bytes(pdf.output())
    except Exception as e:
        st.warning(f"No se pudo generar la ficha: {e}")
        return None




def generar_qr_bytes(texto):
    if not QR_DISPONIBLE:
        return None
    qr = qrcode.QRCode(box_size=6, border=2)
    qr.add_data(texto)
    qr.make(fit=True)
    img = qr.make_image(fill_color="black", back_color="white")
    buf = BytesIO()
    img.save(buf, format="PNG")
    return buf.getvalue()



